    "name": "요청 금액 대조",
    "template": "{\n  \"weave\": \"1\",\n  \"id\": \"asked-amounts-1\",\n  \"title\": \"요청 금액 대조\",\n  \"facets\": [\n    {\n      \"id\": \"match\",\n      \"title\": \"요청 금액 대조\",\n      \"hint\": \"요청한 가입금액과 이 제안서가 넣은 가입금액을 나란히 둔 것입니다.\",\n      \"element\": \"rows\",\n      \"compare\": \"focus\",\n      \"fields\": [\n        {\n          \"key\": \"asked-vs-given\",\n          \"label\": \"담보별\",\n          \"shape\": \"items\",\n          \"description\": \"말한 담보를 말한 순서대로 하나씩. 각 줄에 말한 금액과 이 제안서가 준 금액을 함께 담는다. 제안서가 그 담보를 안 넣었으면 준 금액을 비운다.\",\n          \"hint\": \"말한 금액과 이 제안서가 준 금액을 나란히 둔 것이에요.\",\n          \"columns\": [\n            {\n              \"key\": \"cover\",\n              \"label\": \"담보\",\n              \"type\": \"text\",\n              \"description\": \"말한 담보의 이름 그대로 담는다.\"\n            },\n            {\n              \"key\": \"asked\",\n              \"label\": \"말한 금액\",\n              \"type\": \"money\",\n              \"description\": \"사용자가 말한 가입금액을 원 단위 정수로 담는다.\"\n            },\n            {\n              \"key\": \"given\",\n              \"label\": \"이 제안서\",\n              \"type\": \"money\",\n              \"description\": \"이 제안서가 그 담보에 넣은 가입금액을 원 단위 정수로 담는다.\"\n            }\n          ]\n        }\n      ],\n      \"notes\": [\n        {\n          \"kind\": \"note\",\n          \"text\": \"두 금액을 나란히 두기만 합니다. 어느 쪽이 낫다고 말하지 않습니다.\"\n        },\n        {\n          \"kind\": \"caution\",\n          \"text\": \"같은 이름의 담보라도 보장 범위가 다를 수 있습니다. 금액만으로 견주면 안 됩니다.\"\n        }\n      ]\n    },\n    {\n      \"id\": \"by-cover\",\n      \"title\": \"담보별 가입금액\",\n      \"hint\": \"담보 하나가 한 줄에 서고 칸마다 제안서가 갈립니다.\",\n      \"element\": \"rows\",\n      \"compare\": \"overlay\",\n      \"fields\": [\n        {\n          \"key\": \"cover-list\",\n          \"label\": \"담보별 가입금액\",\n          \"shape\": \"items\",\n          \"description\": \"말한 담보를 하나씩. 각 제안서가 그 담보에 넣은 가입금액을 담는다.\",\n          \"hint\": \"한 줄에 담보 하나, 칸마다 제안서 하나예요.\",\n          \"columns\": [\n            {\n              \"key\": \"cover\",\n              \"label\": \"담보\",\n              \"type\": \"text\",\n              \"description\": \"담보의 이름 그대로 담는다.\"\n            },\n            {\n              \"key\": \"amount\",\n              \"label\": \"가입금액\",\n              \"type\": \"money\",\n              \"description\": \"그 담보의 가입금액을 원 단위 정수로 담는다.\"\n            }\n          ]\n        }\n      ],\n      \"notes\": [\n        {\n          \"kind\": \"note\",\n          \"text\": \"빈 칸은 그 제안서에 그 담보가 없다는 뜻입니다.\"\n        }\n      ]\n    },\n    {\n      \"id\": \"premium\",\n      \"title\": \"월 보험료\",\n      \"hint\": \"이 제안서에서 매달 빠져나가는 금액입니다.\",\n      \"element\": \"stat\",\n      \"fields\": [\n        {\n          \"key\": \"monthly\",\n          \"label\": \"월 보험료\",\n          \"shape\": \"single\",\n          \"description\": \"이 제안서의 월 납입 보험료 총액을 원 단위 정수로.\",\n          \"type\": \"money\",\n          \"hint\": \"이 제안서에서 매달 빠져나가는 돈이에요.\"\n        }\n      ],\n      \"notes\": [\n        {\n          \"kind\": \"caution\",\n          \"text\": \"가입금액을 맞추면 보험료가 오릅니다. 둘을 함께 봅니다.\"\n        }\n      ]\n    },\n    {\n      \"id\": \"terms\",\n      \"title\": \"계약 조건\",\n      \"hint\": \"언제까지 내고 언제까지 받는지, 갱신이 있는지입니다.\",\n      \"element\": \"facts\",\n      \"fields\": [\n        {\n          \"key\": \"pay-period\",\n          \"label\": \"납입기간\",\n          \"shape\": \"single\",\n          \"description\": \"납입기간을 사람이 읽는 표시 그대로. 보기: 20년납.\",\n          \"type\": \"text\",\n          \"hint\": \"보험료를 내는 기간이에요.\"\n        },\n        {\n          \"key\": \"cover-period\",\n          \"label\": \"보장기간\",\n          \"shape\": \"single\",\n          \"description\": \"보장기간을 사람이 읽는 표시 그대로. 보기: 90세만기.\",\n          \"type\": \"text\",\n          \"hint\": \"보장을 받는 기간이에요.\"\n        },\n        {\n          \"key\": \"renewal\",\n          \"label\": \"갱신\",\n          \"shape\": \"single\",\n          \"description\": \"갱신 주기를 사람이 읽는 표시 그대로. 보기: 비갱신.\",\n          \"type\": \"text\",\n          \"hint\": \"몇 년마다 보험료가 다시 매겨지는지예요.\"\n        }\n      ],\n      \"notes\": [\n        {\n          \"kind\": \"tip\",\n          \"text\": \"말한 조건(90세 만기·20년납·비갱신)과 다른 곳이 있으면 여기서 드러납니다.\"\n        }\n      ]\n    }\n  ]\n}\n",
